const limits=Object.fromEntries(editableKeys.map(key=>{const p=formulaFields.get(key);return [key,[p[2],p[3],p[4],REFERENCE_FORMULA_PARAMETERS[key]??p[5]]];}));
const defs=[
{id:'source',title:'输入与球面变换',category:'向量 / 每轮输入',xy:[34,45],desc:'世界坐标进入原公式，球面变换保持参考设置。',formula:'z₀ = 0.6 × P\n变换后得到 r、θ、φ',fields:[]},
{id:'phase',title:'双相位',category:'角度 / 固定关键帧',xy:[34,365],desc:'20 秒线性循环，保持原版锁定区间。',formula:'θ = asin(z/r) + LoopPI\nφ = atan2(y,x) + LoopPI2',fields:[],phase:true},
{id:'power',title:'球面幂次',category:'半径与角度',xy:[348,45],desc:'放大角度并对半径求幂，决定分瓣与展开。',formula:'r′ = r ^ Power\nθ′ = θ × Power\nφ′ = φ × Power',fields:[['Power','幂次 Power']]},
{id:'vector',title:'笛卡尔重建',category:'向量 / 纵向比例',xy:[662,45],desc:'将球面坐标转回向量。Z 倍率只作用于纵向分量。',formula:'q = r′ × (cosθ′ cosφ′,\n cosθ′ sinφ′,\n ZMultiplier × sinθ′)',fields:[['ZMultiplier','Z 倍率']]},
{id:'history',title:'历史向量混合',category:'反馈 / 前两轮结果',xy:[348,405],desc:'在重建向量上加入常量及历史结果。关闭时，两项历史权重归零。',formula:'z_new = q + c\n + prevz × PrevVecMul\n + oldz × OldVecMul',fields:[['PrevVecMul','前向量混合'],['OldVecMul','旧向量混合']],toggle:true},
{id:'feedback',title:'常量反馈',category:'反馈 / 下一轮常量',xy:[662,405],desc:'更新历史向量后，将当前结果反馈给下一轮常量。关闭时 c 保持。',formula:'prevz ← oldz; oldz ← z_new\nc_next = Implode × z_new\n + Explode × c',fields:[['Implode','内收 Implode'],['Explode','外扩 Explode']],toggle:true},
{id:'iteration',title:'迭代与逃逸',category:'控制 / 迭代终止',xy:[976,195],desc:'循环控制，非串行运算。每轮球面变换后、重建与反馈前检查逃逸；次数控制整个循环。',formula:'重复最多 Iterations 次\nr > Bailout 或 r^Power > Bailout\n→ 退出',fields:[['Iterations','迭代次数'],['Bailout','逃逸阈值']]},
{id:'output',title:'距离与表面',category:'输出 / 实时渲染',xy:[976,610],desc:'原公式距离估计交给光线步进，沿用蓝金材质和灯光。',formula:'DE = 0.5 × log(r) × r / dr\n→ 三维表面',fields:[]}
];
const connections=[['source','power'],['phase','power'],['power','vector'],['vector','history'],['history','feedback'],['iteration','source','control'],['iteration','output','control'],['feedback','source','loop']];
let params=Object.fromEntries(Object.entries(limits).map(([k,v])=>[k,v[3]])),enabled={history:true,feedback:true},positions=Object.fromEntries(defs.map(n=>[n.id,[...n.xy]])),zoom=1,pan=[15,15],drag=null,playing=true,ready=false;
const inputs=new Map(),cards=new Map();
function send(action,data={}){q('renderer').contentWindow.postMessage({type:'uber-node-command',action,...data},location.origin);}
function compile(){const values={...params};if(!enabled.history){values.PrevVecMul=0;values.OldVecMul=0;}if(!enabled.feedback){values.Implode=0;values.Explode=1;}send('parameters',{parameters:values});q('graph-status').textContent='已更新节点 · '+(enabled.history?'历史反馈开启':'历史反馈关闭')+' · '+(enabled.feedback?'常量反馈开启':'常量反馈关闭');saveLocal();}
function field(key,label){const el=document.createElement('div');el.className='node-field';const [min,max,step]=limits[key];el.innerHTML='<label for="node-'+key+'"><span>'+label+'</span><input type="number" id="node-'+key+'" min="'+min+'" max="'+max+'" step="'+step+'"></label><input type="range" aria-label="'+label+'滑杆" min="'+min+'" max="'+max+'" step="'+step+'">';const number=el.querySelector('[type=number]'),range=el.querySelector('[type=range]');inputs.set(key,{number,range});const set=raw=>{if(raw==='')return;let n=Number(raw);if(!Number.isFinite(n))return;n=Math.max(min,Math.min(max,n));if(key==='Iterations')n=Math.round(n);params[key]=n;syncFields();compile();};number.oninput=()=>set(number.value);number.onblur=syncFields;range.oninput=()=>set(range.value);return el;}
for(const n of defs){const card=document.createElement('article');card.className='graph-node';card.id='graph-'+n.id;const header=document.createElement('div');header.className='node-grip';header.innerHTML='<div><h3>'+n.title+'</h3><span class="node-category">'+n.category+'</span></div>';if(n.toggle){const b=document.createElement('button');b.type='button';b.id='enable-'+n.id;b.setAttribute('aria-label',n.title+'开关');b.onclick=()=>{enabled[n.id]=!enabled[n.id];syncFields();compile();};header.append(b);}const body=document.createElement('div');body.className='node-content';const p=document.createElement('p');p.textContent=n.desc;body.append(p);for(const [key,label]of n.fields)body.append(field(key,label));const code=document.createElement('code');code.textContent=n.formula;body.append(code);if(n.phase){const r=document.createElement('div');r.className='phase-readout';r.id='phase-readout';r.textContent='LoopPI 1.695 → 0.129\nLoopPI2 3.14 → 0';r.style.whiteSpace='pre-line';body.append(r);}card.append(header,body);for(const dir of ['in','out']){const port=document.createElement('span');port.className='node-port '+dir;port.title=dir==='in'?'公式数据输入':'公式数据输出';card.append(port);}cards.set(n.id,card);q('graph-nodes').append(card);header.onpointerdown=e=>{if(e.target.closest('button'))return;e.preventDefault();header.setPointerCapture(e.pointerId);drag={type:'node',id:n.id,start:[e.clientX,e.clientY],position:[...positions[n.id]]};card.classList.add('selected');};header.onpointermove=e=>{if(!drag||drag.type!=='node'||drag.id!==n.id)return;positions[n.id]=[Math.max(0,Math.min(1550,drag.position[0]+(e.clientX-drag.start[0])/zoom)),Math.max(0,Math.min(1350,drag.position[1]+(e.clientY-drag.start[1])/zoom))];layout();};for(const ev of ['pointerup','pointercancel','lostpointercapture'])header.addEventListener(ev,()=>{if(drag?.type==='node'){drag=null;card.classList.remove('selected');saveLocal();}});}
function syncFields(){for(const [key,{number,range}]of inputs){number.value=params[key];range.value=params[key];const n=defs.find(d=>d.fields.some(f=>f[0]===key));const disabled=n.toggle&&!enabled[n.id];number.disabled=disabled;range.disabled=disabled;}for(const n of defs)if(n.toggle){cards.get(n.id).classList.toggle('bypassed',!enabled[n.id]);const b=q('enable-'+n.id);b.textContent=enabled[n.id]?'开启':'关闭';b.setAttribute('aria-pressed',String(enabled[n.id]));}updateNodeRanges();layout();}
function layout(){for(const n of defs){const [x,y]=positions[n.id];cards.get(n.id).style.left=x+'px';cards.get(n.id).style.top=y+'px';}const svg=q('wires');svg.replaceChildren();for(const [a,b,loop]of connections){const from=positions[a],to=positions[b];const path=document.createElementNS('http://www.w3.org/2000/svg','path');if(loop==='loop'){path.setAttribute('d','M '+(from[0]+126)+' '+(from[1]+cards.get(a).offsetHeight)+' C '+(from[0]+126)+' 970, 18 970, 18 70 L '+to[0]+' 70');path.classList.add('feedback-wire');}else{const x1=from[0]+252,y1=from[1]+26,x2=to[0],y2=to[1]+26,c=Math.max(70,Math.abs(x2-x1)*.45);path.setAttribute('d','M '+x1+' '+y1+' C '+(x1+c)+' '+y1+', '+(x2-c)+' '+y2+', '+x2+' '+y2);}if(loop==='control'){path.classList.add('control-wire');const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=b==='output'?'退出迭代后输出距离':'每轮控制，不是串行运算';path.append(title);}if(enabled[a]===false||enabled[b]===false)path.classList.add('bypassed-wire');svg.append(path);}transform();}
function transform(){q('graph-world').style.transform='translate('+pan[0]+'px,'+pan[1]+'px) scale('+zoom+')';q('graph-zoom').textContent=Math.round(zoom*100)+'%';}
function fit(){const v=q('graph-viewport'),maxX=Math.max(...defs.map(n=>positions[n.id][0]+252))+30,maxY=Math.max(...defs.map(n=>positions[n.id][1]+cards.get(n.id).offsetHeight))+40;zoom=Math.max(.3,Math.min(1,Math.min((v.clientWidth-35)/maxX,(v.clientHeight-30)/Math.max(970,maxY))));pan=[18,18];transform();}
const viewport=q('graph-viewport');viewport.onpointerdown=e=>{if(e.target.closest('.graph-node'))return;viewport.setPointerCapture(e.pointerId);drag={type:'pan',start:[e.clientX,e.clientY],pan:[...pan]};};viewport.onpointermove=e=>{if(drag?.type!=='pan')return;pan=[drag.pan[0]+e.clientX-drag.start[0],drag.pan[1]+e.clientY-drag.start[1]];transform();};for(const ev of ['pointerup','pointercancel','lostpointercapture'])viewport.addEventListener(ev,()=>{if(drag?.type==='pan')drag=null;});
function zoomAt(next,x,y){next=Math.max(.3,Math.min(1.7,next));const ratio=next/zoom;pan=[x-(x-pan[0])*ratio,y-(y-pan[1])*ratio];zoom=next;transform();}
viewport.addEventListener('wheel',e=>{e.preventDefault();const r=viewport.getBoundingClientRect();zoomAt(zoom*Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top);},{passive:false});viewport.onkeydown=e=>{if(e.target!==viewport)return;if(e.key.startsWith('Arrow')){e.preventDefault();if(e.key==='ArrowLeft')pan[0]+=35;if(e.key==='ArrowRight')pan[0]-=35;if(e.key==='ArrowUp')pan[1]+=35;if(e.key==='ArrowDown')pan[1]-=35;transform();}if(['+','=','-'].includes(e.key)){e.preventDefault();zoomAt(zoom*(e.key==='-'?.9:1.1),viewport.clientWidth/2,viewport.clientHeight/2);}};
function graphData(){return{schema:'uber-node-graph-v1',parameters:params,enabled,positions};}
function saveLocal(){try{localStorage.setItem('uber-node-graph-v1',JSON.stringify(graphData()));}catch{}}
function validateGraph(o){if(!o||o.schema!=='uber-node-graph-v1'||!o.parameters||!o.enabled||!o.positions)throw Error('请选择本节点版本导出的 JSON');const next={};for(const [key,[min,max]]of Object.entries(limits)){const n=o.parameters[key];if(!Number.isFinite(n)||n<min||n>max||(key==='Iterations'&&!Number.isInteger(n)))throw Error('参数 '+key+' 无效');next[key]=n;}const on={};for(const k of ['history','feedback']){if(typeof o.enabled[k]!=='boolean')throw Error('节点开关无效');on[k]=o.enabled[k];}const xy={};for(const n of defs){const p=o.positions[n.id];if(!Array.isArray(p)||p.length!==2||!p.every(v=>Number.isFinite(v)&&v>=0&&v<=1550))throw Error('节点位置无效');xy[n.id]=p;}return{next,on,xy};}
try{const raw=localStorage.getItem('uber-node-graph-v1');if(raw&&raw.length<50000){const s=validateGraph(JSON.parse(raw));params=s.next;enabled=s.on;positions=s.xy;}}catch{}
q('fit-graph').onclick=fit;q('reset-graph').onclick=()=>{params=Object.fromEntries(Object.entries(limits).map(([k,v])=>[k,v[3]]));enabled={history:true,feedback:true};positions=Object.fromEntries(defs.map(n=>[n.id,[...n.xy]]));syncFields();fit();compile();};
q('save-graph').onclick=()=>{const blob=new Blob([JSON.stringify(graphData(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='uber-node-graph.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);q('graph-status').textContent='节点参数、开关和排布已导出';};q('load-graph').onclick=()=>q('graph-file').click();q('graph-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>50000)throw Error('文件过大');const s=validateGraph(JSON.parse(await f.text()));params=s.next;enabled=s.on;positions=s.xy;syncFields();fit();compile();}catch(err){q('graph-status').textContent='无法导入：'+err.message;}e.target.value='';};
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==q('renderer').contentWindow||e.data?.type!=='uber-node-state')return;const s=e.data;if(s.ready&&!ready){ready=true;compile();}playing=s.playing;q('node-play').textContent=playing?'暂停动画':'播放动画';q('node-play').setAttribute('aria-pressed',String(playing));q('node-time').value=s.progress;q('node-time-value').textContent=(s.progress*20).toFixed(2)+' s';for(const [i,id]of ['node-phase1','node-phase2'].entries())q(id).innerHTML=phaseDigits(s.phase[i]);updateNodeRanges();q('phase-readout').textContent='LoopPI '+s.phase[0].toFixed(4)+'\nLoopPI2 '+s.phase[1].toFixed(4);q('preview-status').textContent=s.status;q('preview-error').hidden=!s.error;q('preview-error').textContent=s.error;});
q('node-play').onclick=()=>send('play',{value:!playing});q('node-time').oninput=e=>send('progress',{value:Number(e.target.value)});q('node-quality').onchange=e=>send('quality',{value:Number(e.target.value)});q('reference-view').onclick=()=>send('reference');q('top-view').onclick=()=>send('top');q('bottom-view').onclick=()=>send('bottom');q('node-snapshot').onclick=()=>send('snapshot');q('renderer').onload=()=>send('report');for(const n of defs){const option=document.createElement('option');option.value=n.id;option.textContent=n.title;q('focus-node').append(option);}q('focus-node').onchange=e=>{const id=e.target.value;if(!cards.has(id))return;zoom=1;pan=[viewport.clientWidth/2-positions[id][0]-126,Math.max(20,viewport.clientHeight/2-cards.get(id).offsetHeight/2)-positions[id][1]];transform();};q('zoom-in').onclick=()=>zoomAt(zoom*1.2,viewport.clientWidth/2,viewport.clientHeight/2);q('zoom-out').onclick=()=>zoomAt(zoom/1.2,viewport.clientWidth/2,viewport.clientHeight/2);syncFields();requestAnimationFrame(()=>{zoom=.85;pan=[18,18];transform();});new ResizeObserver(transform).observe(viewport);

function updateNodeRanges(){for(const el of document.querySelectorAll('input[type=range]')){const min=Number(el.min)||0,max=Number(el.max)||1;el.style.setProperty('--range-position',((Number(el.value)-min)/(max-min)*100)+'%');}}
